enum Mark { Cold Hot }
struct Position { x: int y: int }
struct Token { position: Position mark: Mark }
fn fallback() -> Token { return Token{position: Position{x: -1, y: -1}, mark: .Cold} }
fn main() {
    var tokens = [Token{position: Position{x: 2, y: 3}, mark: .Cold}, Token{position: Position{x: 5, y: 7}, mark: .Hot}]
    let last = tokens.pop() ?? fallback()
    println(last.position.x + last.position.y)
    println(last.mark == .Hot)
    let first = tokens.pop() ?? fallback()
    println(first.position.x + first.position.y)
    println(first.mark == .Cold)
    println(tokens.pop().isNone())
    var marks: Vec[Mark] = [.Cold, .Hot]
    println((marks.pop() ?? .Cold) == .Hot)
    println((marks.pop() ?? .Hot) == .Cold)
    println((marks.pop() ?? .Hot) == .Hot)
}

struct Stack { values: Vec[int] }
struct Nested { stack: Stack }
fn popValues(values: inout Vec[int]) -> ?int { return values.pop() }
fn popField(stack: inout Stack) -> ?int { return stack.values.pop() }
fn main() {
    var nested = Nested{stack: Stack{values: [10, 20, 30, 40]}}
    println(nested.stack.values.pop() ?? -1)
    println(popField(&nested.stack) ?? -1)
    println(popValues(&nested.stack.values) ?? -1)
    println(nested.stack.values.pop() ?? -1)
    println(popField(&nested.stack) ?? -1)
    println(nested.stack.values.len())
}

struct Slot { index: int active: bool }
fn rewind(values: inout Vec[Slot], count: int) {
    while values.len() > count { let _ = values.pop() }
}
fn main() {
    var values: Vec[Slot] = []
    var index = 0
    while index < 40 {
        values.push(Slot{index: index, active: true})
        index += 1
    }
    rewind(&values, 5)
    println(values.len())
    println((values.pop() ?? Slot{index: -1, active: false}).index)
    rewind(&values, 2)
    values.push(Slot{index: 99, active: false})
    println((values.pop() ?? Slot{index: -1, active: false}).index)
    rewind(&values, 0)
    println(values.pop().isNone())
    index = 0
    while index < 40 {
        let _ = values.pop()
        index += 1
    }
    println(values.len())
}

